// HMAC-SHA256 (RFC 2104) built on the pure-JS SHA-256 in sha256.mjs.

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(key, message) {
  let k = key;
  if (k.length > BLOCK_SIZE) {
    k = sha256(k);
  }
  const ipad = new Uint8Array(BLOCK_SIZE).fill(0x36);
  const opad = new Uint8Array(BLOCK_SIZE).fill(0x5c);
  for (let i = 0; i < k.length; i++) {
    ipad[i] ^= k[i];
    opad[i] ^= k[i];
  }
  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  inner.set(ipad);
  inner.set(message, BLOCK_SIZE);
  const innerHash = sha256(inner);
  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(opad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha256(outer);
}

// Base64url encoding/decoding (RFC 4648 §5), without padding,
// matching the helpers used by JWS/JWT libraries.

export function base64urlEncode(data) {
  // data: Uint8Array
  let binary = '';
  for (let i = 0; i < data.length; i++) {
    binary += String.fromCharCode(data[i]);
  }
  return btoa(binary)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

export function base64urlDecode(str) {
  let s = str.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4 !== 0) {
    s += '=';
  }
  const binary = atob(s);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    out[i] = binary.charCodeAt(i);
  }
  return out;
}

// Python-compatible JSON serialization (json.dumps defaults) and
// Python-compatible repr() for str / dict, so printed output matches
// CPython byte-for-byte.

// --- json.dumps(value, ensure_ascii=True, separators=(', ', ': ')) ---

function escapeJsonString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    switch (ch) {
      case '"': out += '\\"'; continue;
      case '\\': out += '\\\\'; continue;
      case '\b': out += '\\b'; continue;
      case '\f': out += '\\f'; continue;
      case '\n': out += '\\n'; continue;
      case '\r': out += '\\r'; continue;
      case '\t': out += '\\t'; continue;
    }
    if (cp < 0x20) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else if (cp < 0x7f) {
      out += ch;
    } else {
      // ensure_ascii=True: emit UTF-16 code units as \uXXXX escapes
      if (cp > 0xffff) {
        const v = cp - 0x10000;
        const hi = 0xd800 + (v >> 10);
        const lo = 0xdc00 + (v & 0x3ff);
        out += '\\u' + hi.toString(16).padStart(4, '0');
        out += '\\u' + lo.toString(16).padStart(4, '0');
      } else {
        out += '\\u' + cp.toString(16).padStart(4, '0');
      }
    }
  }
  return out + '"';
}

export function pyJsonDumps(value) {
  if (value === null) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (typeof value === 'string') return escapeJsonString(value);
  if (typeof value === 'number') {
    if (Number.isInteger(value)) return String(value);
    return String(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyJsonDumps).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => escapeJsonString(k) + ': ' + pyJsonDumps(value[k])
    );
    return '{' + items.join(', ') + '}';
  }
  throw new TypeError(`Object of type ${typeof value} is not JSON serializable`);
}

