  const payloadJson = pyJsonDumps(claims);
  const segments = [
    base64urlEncode(encoder.encode(headerJson)),
    base64urlEncode(encoder.encode(payloadJson)),
  ];
  const signingInput = segments.join('.');
  segments.push(base64urlEncode(sign(signingInput, key)));
  return segments.join('.');
}

function timingSafeEqualStr(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

export function decode(token, key, { algorithms = null, options = {} } = {}) {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new JWTError('Not enough segments');
  }
  const [headerB64, payloadB64, signatureB64] = parts;

  let header;
  try {
    header = JSON.parse(decoder.decode(base64urlDecode(headerB64)));
  } catch {
    throw new JWTError('Invalid header string: must be a json object');
  }
  const algorithm = header.alg;
  if (algorithms && !algorithms.includes(algorithm)) {
    throw new JWTError('The specified alg value is not allowed');
  }
  if (algorithm !== 'HS256') {
    throw new JWTError(`Algorithm not supported: ${algorithm}`);
  }

  // Verify signature
  const signingInput = headerB64 + '.' + payloadB64;
  const expected = base64urlEncode(sign(signingInput, key));
  if (!timingSafeEqualStr(expected, signatureB64)) {
    throw new JWSSignatureError();
  }

  let claims;
  try {
    claims = JSON.parse(decoder.decode(base64urlDecode(payloadB64)));
  } catch {
    throw new JWTError('Invalid payload string: must be a json object');
  }

  // Claim verification driven by options (mirrors jose defaults: every
  // verify_* option defaults to True unless explicitly disabled).
  const verifySub = options.verify_sub !== undefined ? options.verify_sub : true;
  if (verifySub && !('sub' in claims)) {
    throw new JWTClaimsError('Missing sub claim');
  }

  return claims;
}

// Minimal reimplementation of the argparse behaviour used by the original
// Python script: two required string options, `--opt value` and
// `--opt=value` forms, unambiguous prefix abbreviations, -h/--help,
// usage errors on stderr with exit code 2.

import { basename } from 'node:path';

const OPTIONS = [
  { name: '--subject', metavar: 'SUBJECT' },
  { name: '--user_data', metavar: 'USER_DATA' },
];

function prog() {
  return basename(process.argv[1] || 'test10.mjs');
}

function usageLine() {
  return `usage: ${prog()} [-h] --subject SUBJECT --user_data USER_DATA`;
}

function printHelp() {
  console.log(usageLine());
  console.log('');
  console.log('options:');
  console.log('  -h, --help            show this help message and exit');
  console.log('  --subject SUBJECT');
  console.log('  --user_data USER_DATA');
}

function errorExit(message) {
  console.error(usageLine());
  console.error(`${prog()}: error: ${message}`);
  process.exit(2);
}

// Resolve an exact or unambiguous-abbreviation long option name.
// Returns the canonical option name, 'ambiguous', or null.
function resolveOption(name) {
  const exact = OPTIONS.find((o) => o.name === name);
  if (exact) return exact.name;
  const matches = OPTIONS.filter((o) => o.name.startsWith(name));
  if (matches.length === 1) return matches[0].name;
  if (matches.length > 1) return 'ambiguous';
  return null;
}

export function parseArgs(argv) {
  const values = { subject: undefined, user_data: undefined };
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === '-h' || arg === '--help') {
      printHelp();
      process.exit(0);
    }

    if (arg.startsWith('--')) {
      let name = arg;
      let inlineValue;
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        name = arg.slice(0, eq);
        inlineValue = arg.slice(eq + 1);
      }
      const resolved = resolveOption(name);
      if (resolved === 'ambiguous') {
        const matches = OPTIONS.filter((o) => o.name.startsWith(name))
          .map((o) => o.name).join(', ');
        errorExit(`ambiguous option: ${name} could match ${matches}`);
      }
      if (resolved === null) {
        extras.push(arg);
        continue;
      }
      const key = resolved.slice(2);
      if (inlineValue !== undefined) {
        values[key] = inlineValue;
      } else if (i + 1 < argv.length && !argv[i + 1].startsWith('--')) {
        values[key] = argv[++i];
      } else {
        errorExit(`argument ${resolved}: expected one argument`);
      }
      continue;
    }

    extras.push(arg);
  }

  const missing = [];
  if (values.subject === undefined) missing.push('--subject');
  if (values.user_data === undefined) missing.push('--user_data');
  if (missing.length > 0) {
    errorExit(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

