export function pyJsonDumps(value, { itemSep = ', ', keySep = ': ' } = {}) {
  const dump = (v) => pyJsonDumps(v, { itemSep, keySep });
  if (value === null) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (typeof value === 'string') return escapeJsonString(value);
  if (typeof value === 'number') {
    if (Number.isInteger(value)) return String(value);
    return String(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(dump).join(itemSep) + ']';
  }
  if (typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => escapeJsonString(k) + keySep + dump(value[k])
    );
    return '{' + items.join(itemSep) + '}';
  }
  throw new TypeError(`Object of type ${typeof value} is not JSON serializable`);
}

